def get_full_html(cesium_token: str, elements: str):
    return '<html lang="en"> <head> <meta charset="utf-8"> <script src="https://cesium.com/downloads/cesiumjs/releases/1.110/Build/Cesium/Cesium.js"></script> <link href="https://cesium.com/downloads/cesiumjs/releases/1.110/Build/Cesium/Widgets/widgets.css" rel="stylesheet"> <script src="/output_lab/cesium_project/display_two_points.js"></script> <title>Cesium Viewer</title> </head> <body> <div id="cesiumContainer" style="width: 100%; height:100%"></div> <script> Cesium.Ion.defaultAccessToken = "{cesium_token}"; const viewer = new Cesium.Viewer("cesiumContainer", {{ skyBox: false, skyAtmosphere: false, baseLayerPicker: true, geocoder: false, homeButton: false, infoBox: false, sceneModePicker: false, navigationHelpButton: false, shouldAnimate: true, contextOptions: {{ webgl: {{ alpha: true }} }} }}); var scene = viewer.scene; scene.backgroundColor = Cesium.Color.WHITESMOKE; {get_elements} </script> </body>'.format(
        cesium_token=cesium_token, get_elements=elements
    )
